import{_ as d,o as e,c as o,a0 as r}from"./chunks/framework.DoRPXVp_.js";const u=JSON.parse('{"title":"AI Agent Security — Capability Verification","description":"","frontmatter":{"title":"AI Agent Security — Capability Verification"},"headers":[],"relativePath":"competitiveness.md","filePath":"competitiveness.md"}'),a={name:"competitiveness.md"};function c(n,t,i,s,l,h){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="ai-agent-security-what-lattice-actually-delivers" tabindex="-1">AI Agent Security: What Lattice Actually Delivers <a class="header-anchor" href="#ai-agent-security-what-lattice-actually-delivers" aria-label="Permalink to &quot;AI Agent Security: What Lattice Actually Delivers&quot;">​</a></h1><blockquote><p>对照&quot;AI Agent 零信任沙箱&quot;这一商业定位，以实际代码验证每项能力的实现状态。 最后更新: 2026-05-18，基于 <code>cmd/lattice/cmd/sandbox/</code>、<code>internal/agent/gvisor/</code>、<code>api/v1alpha1/</code> 源码。</p></blockquote><h2 id="三大核心场景-代码级验证" tabindex="-1">三大核心场景：代码级验证 <a class="header-anchor" href="#三大核心场景-代码级验证" aria-label="Permalink to &quot;三大核心场景：代码级验证&quot;">​</a></h2><h3 id="场景-1-agent-间-阅后即焚-加密私有网" tabindex="-1">场景 1：Agent 间&quot;阅后即焚&quot;加密私有网 <a class="header-anchor" href="#场景-1-agent-间-阅后即焚-加密私有网" aria-label="Permalink to &quot;场景 1：Agent 间&quot;阅后即焚&quot;加密私有网&quot;">​</a></h3><blockquote><p>主控系统通过 CRD 声明，一瞬间为两个 Agent 拉起专属 WireGuard 加密隧道。任务结束自动回收，不留痕迹。</p></blockquote><table tabindex="0"><thead><tr><th>能力点</th><th>状态</th><th>代码位置</th></tr></thead><tbody><tr><td>AgentIdentity CRD 声明式创建</td><td>✅ 已实现</td><td><code>api/v1alpha1/agent_identity_types.go</code></td></tr><tr><td>每个 Agent 独立 WireGuard keypair</td><td>✅ 已实现</td><td><code>cmd/lattice/cmd/sandbox/sandbox_shared.go:28</code> — <code>sandboxCredentials{PrivateKey, JWT}</code></td></tr><tr><td>Manager reconciler 自动下发 peer 配置</td><td>✅ 已实现</td><td><code>internal/server/controller/agent_identity_controller.go</code></td></tr><tr><td>网络隔离 (default-deny)</td><td>✅ 已实现</td><td><code>LatticePolicy</code> CRD + iptables/eBPF enforcer</td></tr><tr><td>TTL 自动过期</td><td>⚠️ 部分实现</td><td>Phase 切换到 <code>AgentPhaseExpired</code>，但 <strong>不删除 CRD</strong>（<code>agent_identity_controller.go:60-68</code>）</td></tr><tr><td>任务结束网络资源回收</td><td>❌ 未实现</td><td>无 CRD 垃圾回收逻辑（GC）</td></tr></tbody></table><p><strong>诚实评估：核心路径 80% 打通。&quot;阅后即焚&quot;的&quot;焚&quot;差最后一步 GC。</strong></p><hr><h3 id="场景-2-外部-api-调用墙-strict-egress-control" tabindex="-1">场景 2：外部 API 调用墙（Strict Egress Control） <a class="header-anchor" href="#场景-2-外部-api-调用墙-strict-egress-control" aria-label="Permalink to &quot;场景 2：外部 API 调用墙（Strict Egress Control）&quot;">​</a></h3><blockquote><p>对 Agent 实施极其严苛的白名单机制，精细到域名和 L7 层。未授权的 IP 直接在数据面默默丢包。</p></blockquote><table tabindex="0"><thead><tr><th>能力点</th><th>状态</th><th>代码位置</th></tr></thead><tbody><tr><td>CIDR 白名单 (<code>--egress-allow</code>)</td><td>✅ PRO 已实现</td><td><code>sandbox_pro.go:92-105</code> — <code>net.ParseCIDR</code></td></tr><tr><td>默认 deny + Drop</td><td>✅ PRO 已实现</td><td><code>sandbox_pro.go:73</code> — <code>--egress-default-deny</code></td></tr><tr><td>SOCKS5 正向代理</td><td>✅ PRO 已实现</td><td><code>sandbox_pro.go</code> — <code>socks5Server</code>（RFC 1928）</td></tr><tr><td>ForwardListener（端口转发）</td><td>✅ PRO 已实现</td><td><code>sandbox_pro.go:236</code> — <code>shimfwd.NewForwardListener</code></td></tr><tr><td>Community 版 egress 控制</td><td>❌ 完全没有</td><td><code>sandbox_community.go:56-63</code> 只有 <code>--name/--server-url/--token</code></td></tr><tr><td><strong>域名级过滤</strong></td><td>❌ 未实现</td><td><code>PolicyAdapter.Allow</code> 签名只有 <code>dstIP + dstPort</code>（<code>shim_adapter.go:44</code>），没有 DNS 解析</td></tr><tr><td><strong>L7 层过滤</strong>（HTTP path/method/header）</td><td>❌ 未实现</td><td>无相关代码</td></tr></tbody></table><p><strong>诚实评估：&quot;精细到域名和 L7 层&quot;目前不成立。只有 CIDR（IP 级）白名单。</strong></p><hr><h3 id="场景-3-多云-混合云-agent-跨境协同" tabindex="-1">场景 3：多云/混合云 Agent 跨境协同 <a class="header-anchor" href="#场景-3-多云-混合云-agent-跨境协同" aria-label="Permalink to &quot;场景 3：多云/混合云 Agent 跨境协同&quot;">​</a></h3><blockquote><p>无缝编排跨云 K8s 节点，内地和海外 Agent 在同一个超轻量&quot;虚拟大内网&quot;里通信，干掉昂贵专线。</p></blockquote><table tabindex="0"><thead><tr><th>能力点</th><th>状态</th><th>代码位置</th></tr></thead><tbody><tr><td>WireGuard overlay 跨集群</td><td>✅ 已实现</td><td><code>cmd/lattice</code> + <code>cmd/manager</code></td></tr><tr><td>ICE NAT 穿透（pion/ice v4）</td><td>✅ 已实现</td><td><code>internal/agent/transport/</code></td></tr><tr><td>LRP relay 兜底（QUIC）</td><td>✅ 已实现</td><td><code>internal/agent/transport/</code> + WRRP/QUIC</td></tr><tr><td>Cluster Peering CRD</td><td>✅ 已实现</td><td><code>api/v1alpha1/</code></td></tr><tr><td>Network Peering</td><td>✅ 已实现</td><td><code>features/network-peering</code></td></tr><tr><td>加密端到端通信</td><td>✅ 已实现</td><td>WireGuard 内核/用户态实现</td></tr></tbody></table><p><strong>诚实评估：场景 3 基本全部实现。这是 Lattice 最成熟的能力。</strong></p><hr><h2 id="完整能力矩阵-代码验证版" tabindex="-1">完整能力矩阵（代码验证版） <a class="header-anchor" href="#完整能力矩阵-代码验证版" aria-label="Permalink to &quot;完整能力矩阵（代码验证版）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>Community</th><th>Pro</th><th>验证文件</th></tr></thead><tbody><tr><td>WireGuard 加密隧道</td><td>✅</td><td>✅</td><td><code>cmd/lattice</code></td></tr><tr><td>ICE NAT 穿透 (STUN/TURN)</td><td>✅</td><td>✅</td><td><code>internal/agent/transport/</code></td></tr><tr><td>LRP relay (TCP + QUIC)</td><td>✅</td><td>✅</td><td><code>internal/agent/transport/</code></td></tr><tr><td>K8s CRD Operator (kubebuilder)</td><td>✅</td><td>✅</td><td><code>cmd/manager</code></td></tr><tr><td>Dashboard UI</td><td>✅</td><td>✅</td><td><code>fronted/</code></td></tr><tr><td>gVisor 零权限沙箱</td><td>✅</td><td>✅</td><td><code>internal/agent/gvisor/</code></td></tr><tr><td>凭证持久化（重启恢复，mode 0600）</td><td>✅</td><td>✅</td><td><code>sandbox_shared.go:42-65</code></td></tr><tr><td>本地审计日志 (JSONL)</td><td>✅</td><td>✅</td><td><code>sandbox_community.go:67</code></td></tr><tr><td>MCP Tool Tracing (<code>la_tool_spans</code>)</td><td>✅</td><td>✅</td><td><code>models/tool_span.go</code></td></tr><tr><td>Sub-agent Delegate API</td><td>✅</td><td>✅</td><td><code>agent_isolation_router.go:47</code></td></tr><tr><td>TTL 自动过期（设 phase=Expired）</td><td>✅</td><td>✅</td><td><code>agent_identity_controller.go:60</code></td></tr><tr><td>CIDR EgressFilter (<code>--egress-allow</code>)</td><td>❌</td><td>✅</td><td><code>sandbox_pro.go:92-105</code></td></tr><tr><td>ForwardListener (<code>--forward</code>)</td><td>❌</td><td>✅</td><td><code>sandbox_pro.go:236</code></td></tr><tr><td>SOCKS5 代理 (<code>--proxy-addr</code>)</td><td>❌</td><td>✅</td><td><code>sandbox_pro.go</code> — <code>socks5Server</code></td></tr><tr><td>NATS 服务端流量审计 (<code>la_flow_events</code>)</td><td>❌</td><td>✅</td><td><code>audit_consumer_pro.go</code></td></tr><tr><td>Sandbox→NATS 审计推送 (<code>natsAuditWriter</code>)</td><td>❌</td><td>❌</td><td>已规划，标注&quot;待实现&quot;</td></tr><tr><td>域名级 egress 过滤</td><td>❌</td><td>❌</td><td>不存在</td></tr><tr><td>L7 (HTTP) 过滤</td><td>❌</td><td>❌</td><td>不存在</td></tr><tr><td>TTL 到期 CRD 自动清理 (GC)</td><td>❌</td><td>❌</td><td>不存在</td></tr></tbody></table><hr><h2 id="与竞品的差异化" tabindex="-1">与竞品的差异化 <a class="header-anchor" href="#与竞品的差异化" aria-label="Permalink to &quot;与竞品的差异化&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>Calico / Cilium</th><th>Lattice</th></tr></thead><tbody><tr><td>核心定位</td><td>K8s CNI 网络插件</td><td>AI Agent 零信任网络沙箱</td></tr><tr><td>网络模型</td><td>扁平 / 三层路由</td><td>WireGuard 加密 overlay mesh</td></tr><tr><td>Agent 隔离</td><td>靠 NetworkPolicy（IP/port）</td><td>gVisor 用户态沙箱 + WireGuard 身份</td></tr><tr><td>Agent 身份</td><td>Pod IP / ServiceAccount</td><td>WireGuard 公钥 + AgentIdentity CRD</td></tr><tr><td>跨集群</td><td>需要额外配置（多集群 mesh）</td><td>原生 Cluster Peering CRD</td></tr><tr><td>NAT 穿透</td><td>不适用</td><td>ICE + LRP relay</td></tr><tr><td>零权限部署</td><td>需要 privileged DaemonSet</td><td><code>lattice sandbox start</code> 不需要 root</td></tr><tr><td>AI 框架集成</td><td>无</td><td>Python SDK + MCP Server</td></tr><tr><td>TTL 自动过期</td><td>无</td><td>AgentIdentity.ExpiresAt</td></tr><tr><td>审计追踪</td><td>依赖外部系统</td><td>MCP tool spans + 流量审计</td></tr><tr><td>eBPF</td><td>Cilium 的强项</td><td>PRO 有 eBPF TC enforcer，Community 用 iptables</td></tr></tbody></table><hr><h2 id="当前技术差距与下一步" tabindex="-1">当前技术差距与下一步 <a class="header-anchor" href="#当前技术差距与下一步" aria-label="Permalink to &quot;当前技术差距与下一步&quot;">​</a></h2><ol><li><strong>域名/L7 过滤</strong> — gVisor netstack 内做 DNS 拦截 + 动态 IP 映射，工作量中等</li><li><strong>CRD GC</strong> — TTL 到期后删除 AgentIdentity / LatticePeer，工作量小</li><li><strong>natsAuditWriter</strong> — sandbox 侧将审计事件发布到 NATS，文档已标注&quot;待实现&quot;</li><li><strong>Community 版 egress 控制</strong> — 至少给一个 <code>--egress-allow</code> 的 Community 简化版</li></ol>',26)])])}const b=d(a,[["render",c]]);export{u as __pageData,b as default};
